#pragma once
inline nlohmann::json sceneTextureProof(hb::gpu::SceneRenderer& r,const hb::gpu::SceneRenderer::Mesh& mesh,const nlohmann::json& cases){
    using namespace hb::gpu;const std::vector<std::array<std::uint8_t,4>> colors={{{255,0,0,255}},{{0,255,0,255}},{{0,0,255,255}},{{0,255,255,255}},{{255,0,255,255}},{{255,255,0,255}}};
    std::vector<std::uint8_t> faces;for(const auto& color:colors)for(int i=0;i<4;i++)faces.insert(faces.end(),color.begin(),color.end());
    auto cube=r.createDataTexture(2,2,faces,4,false,6,false,false,"cube",true),array=r.createDataTexture(1,1,{255,0,0,255,0,255,255,255},4,false,2,false,true),volume=r.createDataTexture(1,1,{255,0,0,255,0,255,255,255},4,false,2,false,false,"volume");assert(cube.storageBytes()==120&&array.storageBytes()==8&&volume.storageBytes()==8);
    rejects([&]{r.createDataTexture(1,2,faces,4,false,6,false,false,"cube");});rejects([&]{r.createDataTexture(2,2,faces,4,false,5,false,false,"cube");});rejects([&]{r.createDataTexture(1,1,{0,0,0,0},4,false,1,false,true,"volume");});rejects([&]{r.createDataTexture(2049,1,{},4,false,1,false,false,"volume");});rejects([&]{r.createDataTexture(1,1,{},4,false,2);});
    SceneMaterial m;m.unlit=true;m.toneMapped=false;m.color={0,0,0,1};SceneFrame f;f.ambient={0,0,0,1};const auto center=(32*64+32)*4;const auto pixel=[&](const SceneRenderer::Program& p,const SceneRenderer::Texture& t,std::uint32_t sampling){r.begin(f);r.draw(mesh,identity,identity,m,{}, {},0,0,&p,{&t},{sampling});const auto bytes=r.readPixels();return std::array<int,3>{bytes[center],bytes[center+1],bytes[center+2]};};
    nlohmann::json samples=nlohmann::json::array();std::size_t face=0;for(const auto& entry:cases){if(!entry.contains("type"))continue;auto p=r.createProgram(entry.at("declarations"),entry.at("evaluation"),entry.at("uniforms").get<std::vector<float>>());const std::string type=entry.at("type");const auto& t=type=="texturecube"?cube:type=="texturearray"?array:volume;const auto rgba=pixel(p,t,0);if(type=="texturecube"){for(int c=0;c<3;c++)assert(std::abs(rgba[c]-colors[face][c])<3);++face;}else if(type=="texturearray"){const bool cyan=entry.at("value").get<float>()>=.5f;assert(rgba[cyan?1:0]>250&&rgba[cyan?0:1]<3);}else{const auto z=entry.at("value").at(2).get<float>();if(z==.5f)assert(std::abs(rgba[0]-128)<3&&std::abs(rgba[0]-rgba[1])<3&&std::abs(rgba[0]-rgba[2])<3);else assert(z==.75f?rgba[1]>250&&rgba[0]<3:rgba[0]>250&&rgba[1]<3);if(z>1){const auto clamped=pixel(p,t,36);assert(clamped[1]>250&&clamped[0]<3);}}
        samples.push_back({{"type",type},{"value",entry.at("value")},{"rgb",rgba}});}
    const std::string decl="TextureCube t:register(t8);SamplerState s:register(s0);",eval="base.rgb=t.SampleLevel(s,float3(1,0,0),1).rgb;base.a=1;";auto lod=r.createProgram(decl,eval,{});assert(pixel(lod,cube,0)[0]>250);
    auto srgb=r.createDataTexture(1,1,{128,128,128,255},4,false,1,true);auto gray=r.createProgram("Texture2D t:register(t8);SamplerState s:register(s0);","base.rgb=t.Sample(s,float2(.5,.5)).rgb;base.a=1;",{});assert(std::abs(pixel(gray,srgb,0)[0]-128)<3);
    return {{"samples",samples},{"sixFaces",true},{"cubeMipLOD",true},{"arrayHalfUpLayer",true},{"volumeInterpolation",true},{"independentWrapR",true},{"srgbDecode",true},{"dimensionValidation",true},{"mipStorageBytes",cube.storageBytes()}};
}
